package com.example.workout.shoe.service; import static org.assertj.core.api.Assertions.*; import static org.mockito.Mockito.*; import com.example.workout.shoe.entity.RunningShoeEntity; import com.example.workout.shoe.repository.RunningShoeRepository; import com.example.workout.workout.repository.WorkoutRepository; import java.util.Optional; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; @ExtendWith(MockitoExtension.class) class RunningShoeServiceImplTest { @Mock RunningShoeRepository repository; @Mock WorkoutRepository workoutRepository; @InjectMocks RunningShoeServiceImpl service; @Test void delete_unreferenced_shoe_ok(){var entity=RunningShoeEntity.builder().withId(1L).withBrand("B").withModel("M").withInitialDistanceMeters(0L).withActive(true).build();when(repository.findById(1L)).thenReturn(Optional.of(entity));when(workoutRepository.existsByShoeId(1L)).thenReturn(false);service.delete(1L);verify(repository).delete(entity);} }
